import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64
.visible .entry matmul_kernel(
    .param .u64 param_A,
    .param .u64 param_B,
    .param .u64 param_C,
    .param .u32 param_n
)
{
    .reg .b32 %r_tx, %r_ty, %r_bx, %r_by, %r_n, %r_kt;
    .reg .b32 %r_tid, %r_r0, %r_c, %r_k, %r_row, %r_col, %r_tmp, %r_pid, %r_ng, %r_gs, %r_gid, %r_fm, %r_gm;
    .reg .b32 %r_row0, %r_col0, %r_sA, %r_sB, %r_saddr, %r_saddrA, %r_saddrA2;
    .reg .b32 %r_saddrB, %r_saddrB2, %r_aBase, %r_bBase, %r_ab, %r_bb;
    .reg .b32 %r_buf, %r_nbuf;
    .reg .b64 %rd_A, %rd_B, %rd_C, %rd_off, %rd_addr, %rd_rowstride;
    .reg .b64 %rd_Arow, %rd_Arow2, %rd_Bbase, %rd_Bbase2, %rd_gA, %rd_gB;
    .reg .b64 %rd_Bstep;
    .reg .f32 %f_a0, %f_a1, %f_a2, %f_a3, %f_a4, %f_a5, %f_a6, %f_a7;
    .reg .f32 %f_b0, %f_b1, %f_b2, %f_b3;
    .reg .f32 %f_pa0, %f_pa1, %f_pa2, %f_pa3, %f_pa4, %f_pa5, %f_pa6, %f_pa7;
    .reg .f32 %f_acc0, %f_acc1, %f_acc2, %f_acc3, %f_acc4, %f_acc5, %f_acc6, %f_acc7;
    .reg .f32 %f_acc8, %f_acc9, %f_acc10, %f_acc11, %f_acc12, %f_acc13, %f_acc14, %f_acc15;
    .reg .f32 %f_acc16, %f_acc17, %f_acc18, %f_acc19, %f_acc20, %f_acc21, %f_acc22, %f_acc23;
    .reg .f32 %f_acc24, %f_acc25, %f_acc26, %f_acc27, %f_acc28, %f_acc29, %f_acc30, %f_acc31;
    .reg .pred %p1;
    // 64x64 CTA tile, 16-wide K tile, 128 threads (16x8).
    // Thread-level tiling 8x4: each thread computes an 8x4 sub-tile
    // (32 FP32 accumulators); 12 shared-operand floats feed 32 FMAs.
    // True software-pipelined double buffering (sm_89 cp.async): the
    // next K-tile prefetch - A via two ld.global.v4 into registers for
    // the transposed sA staging, B via two 16B cp.async copies - is
    // issued right after the stage barrier, BEFORE the 512-FMA body,
    // so global-load latency overlaps a full compute window instead of
    // stalling between iterations. sA[k][r] (A transposed) and sB[k][c]
    // are padded to 68 floats/row, 2 stages; the A/B global pointers
    // simply advance by one K-tile per iteration. C uses st.global.v4.
    .shared .align 16 .b8 sA[8704];
    .shared .align 16 .b8 sB[8704];
    mov.u32 %r_tx, %tid.x;
    mov.u32 %r_ty, %tid.y;
    ld.param.u64 %rd_A, [param_A];
    ld.param.u64 %rd_B, [param_B];
    ld.param.u64 %rd_C, [param_C];
    ld.param.u32 %r_n, [param_n];
    // Swizzled CTA rasterization: launch is 1D, remap linear CTA id to
    // (bx, by) in groups of 8 row-tiles to improve L2 reuse of A/B tiles.
    mov.u32 %r_pid, %ctaid.x;
    shr.b32 %r_ng, %r_n, 6;
    shl.b32 %r_gs, %r_ng, 3;
    div.u32 %r_gid, %r_pid, %r_gs;
    rem.u32 %r_tmp, %r_pid, %r_gs;
    shl.b32 %r_fm, %r_gid, 3;
    sub.u32 %r_gm, %r_ng, %r_fm;
    min.u32 %r_gm, %r_gm, 8;
    div.u32 %r_bx, %r_tmp, %r_gm;
    rem.u32 %r_tmp, %r_tmp, %r_gm;
    add.u32 %r_by, %r_fm, %r_tmp;
    shl.b32 %r_bx, %r_bx, 6;
    shl.b32 %r_by, %r_by, 6;
    mov.u32 %r_sA, sA;
    mov.u32 %r_sB, sB;
    shl.b32 %r_tid, %r_ty, 4;
    add.u32 %r_tid, %r_tid, %r_tx;
    shl.b32 %r_row0, %r_ty, 3;
    add.u32 %r_row0, %r_row0, %r_by;
    shl.b32 %r_col0, %r_tx, 2;
    add.u32 %r_col0, %r_col0, %r_bx;
    shl.b32 %r_aBase, %r_ty, 5;
    add.u32 %r_aBase, %r_aBase, %r_sA;
    shl.b32 %r_bBase, %r_tx, 4;
    add.u32 %r_bBase, %r_bBase, %r_sB;
    mov.f32 %f_acc0, 0f00000000;
    mov.f32 %f_acc1, 0f00000000;
    mov.f32 %f_acc2, 0f00000000;
    mov.f32 %f_acc3, 0f00000000;
    mov.f32 %f_acc4, 0f00000000;
    mov.f32 %f_acc5, 0f00000000;
    mov.f32 %f_acc6, 0f00000000;
    mov.f32 %f_acc7, 0f00000000;
    mov.f32 %f_acc8, 0f00000000;
    mov.f32 %f_acc9, 0f00000000;
    mov.f32 %f_acc10, 0f00000000;
    mov.f32 %f_acc11, 0f00000000;
    mov.f32 %f_acc12, 0f00000000;
    mov.f32 %f_acc13, 0f00000000;
    mov.f32 %f_acc14, 0f00000000;
    mov.f32 %f_acc15, 0f00000000;
    mov.f32 %f_acc16, 0f00000000;
    mov.f32 %f_acc17, 0f00000000;
    mov.f32 %f_acc18, 0f00000000;
    mov.f32 %f_acc19, 0f00000000;
    mov.f32 %f_acc20, 0f00000000;
    mov.f32 %f_acc21, 0f00000000;
    mov.f32 %f_acc22, 0f00000000;
    mov.f32 %f_acc23, 0f00000000;
    mov.f32 %f_acc24, 0f00000000;
    mov.f32 %f_acc25, 0f00000000;
    mov.f32 %f_acc26, 0f00000000;
    mov.f32 %f_acc27, 0f00000000;
    mov.f32 %f_acc28, 0f00000000;
    mov.f32 %f_acc29, 0f00000000;
    mov.f32 %f_acc30, 0f00000000;
    mov.f32 %f_acc31, 0f00000000;
    // ---- precompute per-thread staging bases (128 threads, two slots each) ----
    // A: transposed float4 staging, rows tid/4 and tid/4+32, k-cols (tid%4)*4.
    shr.b32 %r_r0, %r_tid, 2;
    and.b32 %r_c, %r_tid, 3;
    shl.b32 %r_c, %r_c, 2;
    add.u32 %r_row, %r_by, %r_r0;
    mul.lo.u32 %r_tmp, %r_row, %r_n;
    add.u32 %r_tmp, %r_tmp, %r_c;
    mul.wide.u32 %rd_off, %r_tmp, 4;
    add.u64 %rd_Arow, %rd_A, %rd_off;
    cvt.u64.u32 %rd_off, %r_n;
    shl.b64 %rd_off, %rd_off, 7;
    add.u64 %rd_Arow2, %rd_Arow, %rd_off;
    mul.lo.u32 %r_saddrA, %r_c, 68;
    add.u32 %r_saddrA, %r_saddrA, %r_r0;
    shl.b32 %r_saddrA, %r_saddrA, 2;
    add.u32 %r_saddrA, %r_saddrA, %r_sA;
    add.u32 %r_saddrA2, %r_saddrA, 128;
    // B: float4 cp.async staging, k-rows tid/16 and tid/16+8, cols (tid%16)*4.
    shr.b32 %r_k, %r_tid, 4;
    and.b32 %r_c, %r_tid, 15;
    shl.b32 %r_c, %r_c, 2;
    add.u32 %r_col, %r_bx, %r_c;
    mul.lo.u32 %r_tmp, %r_k, %r_n;
    add.u32 %r_tmp, %r_tmp, %r_col;
    mul.wide.u32 %rd_off, %r_tmp, 4;
    add.u64 %rd_Bbase, %rd_B, %rd_off;
    cvt.u64.u32 %rd_off, %r_n;
    shl.b64 %rd_off, %rd_off, 5;
    add.u64 %rd_Bbase2, %rd_Bbase, %rd_off;
    mul.lo.u32 %r_saddrB, %r_k, 68;
    add.u32 %r_saddrB, %r_saddrB, %r_c;
    shl.b32 %r_saddrB, %r_saddrB, 2;
    add.u32 %r_saddrB, %r_saddrB, %r_sB;
    add.u32 %r_saddrB2, %r_saddrB, 2176;
    mov.u32 %r_kt, 0;
    mov.u32 %r_buf, 0;
    mov.u32 %r_nbuf, 4352;
    // K-tile pointer steps: A advances 16 floats (64B) along a row,
    // B advances 16 rows (16*n*4 = n<<6 bytes).
    cvt.u64.u32 %rd_Bstep, %r_n;
    shl.b64 %rd_Bstep, %rd_Bstep, 6;
    // ---- prologue: prefetch K-tile 0 (A into regs, B via cp.async stage 0) ----
    ld.global.nc.v4.f32 {%f_pa0, %f_pa1, %f_pa2, %f_pa3}, [%rd_Arow];
    ld.global.nc.v4.f32 {%f_pa4, %f_pa5, %f_pa6, %f_pa7}, [%rd_Arow2];
    add.u64 %rd_Arow, %rd_Arow, 64;
    add.u64 %rd_Arow2, %rd_Arow2, 64;
    cp.async.cg.shared.global [%r_saddrB], [%rd_Bbase], 16;
    cp.async.cg.shared.global [%r_saddrB2], [%rd_Bbase2], 16;
    add.u64 %rd_Bbase, %rd_Bbase, %rd_Bstep;
    add.u64 %rd_Bbase2, %rd_Bbase2, %rd_Bstep;
    cp.async.commit_group;
$mm_outer:
    // stage prefetched A registers into the current sA stage (transposed)
    add.u32 %r_saddr, %r_saddrA, %r_buf;
    st.shared.f32 [%r_saddr], %f_pa0;
    st.shared.f32 [%r_saddr+272], %f_pa1;
    st.shared.f32 [%r_saddr+544], %f_pa2;
    st.shared.f32 [%r_saddr+816], %f_pa3;
    add.u32 %r_saddr, %r_saddrA2, %r_buf;
    st.shared.f32 [%r_saddr], %f_pa4;
    st.shared.f32 [%r_saddr+272], %f_pa5;
    st.shared.f32 [%r_saddr+544], %f_pa6;
    st.shared.f32 [%r_saddr+816], %f_pa7;
    add.u32 %r_ab, %r_aBase, %r_buf;
    add.u32 %r_bb, %r_bBase, %r_buf;
    // wait for the B cp.async stage; one barrier publishes both stages
    cp.async.wait_group 0;
    bar.sync 0;
    // ---- issue the next K-tile prefetch BEFORE the FMA body: the
    // ---- global-load latency now overlaps the full 512-FMA compute
    // ---- window below (previously the loads were issued after the
    // ---- compute and waited on immediately at the next iteration,
    // ---- exposing the entire global latency between K-tiles).
    add.u32 %r_kt, %r_kt, 16;
    setp.lt.u32 %p1, %r_kt, %r_n;
    @!%p1 bra $mm_compute;
    ld.global.nc.v4.f32 {%f_pa0, %f_pa1, %f_pa2, %f_pa3}, [%rd_Arow];
    ld.global.nc.v4.f32 {%f_pa4, %f_pa5, %f_pa6, %f_pa7}, [%rd_Arow2];
    add.u64 %rd_Arow, %rd_Arow, 64;
    add.u64 %rd_Arow2, %rd_Arow2, 64;
    add.u32 %r_saddr, %r_saddrB, %r_nbuf;
    cp.async.cg.shared.global [%r_saddr], [%rd_Bbase], 16;
    add.u32 %r_saddr, %r_saddrB2, %r_nbuf;
    cp.async.cg.shared.global [%r_saddr], [%rd_Bbase2], 16;
    add.u64 %rd_Bbase, %rd_Bbase, %rd_Bstep;
    add.u64 %rd_Bbase2, %rd_Bbase2, %rd_Bstep;
    cp.async.commit_group;
$mm_compute:
    // ---- 8x4 register-blocked inner product, fully unrolled over K tile ----
    ld.shared.v4.f32 {%f_a0, %f_a1, %f_a2, %f_a3}, [%r_ab+0];
    ld.shared.v4.f32 {%f_a4, %f_a5, %f_a6, %f_a7}, [%r_ab+16];
    ld.shared.v4.f32 {%f_b0, %f_b1, %f_b2, %f_b3}, [%r_bb+0];
    fma.rn.f32 %f_acc0, %f_a0, %f_b0, %f_acc0;
    fma.rn.f32 %f_acc1, %f_a0, %f_b1, %f_acc1;
    fma.rn.f32 %f_acc2, %f_a0, %f_b2, %f_acc2;
    fma.rn.f32 %f_acc3, %f_a0, %f_b3, %f_acc3;
    fma.rn.f32 %f_acc4, %f_a1, %f_b0, %f_acc4;
    fma.rn.f32 %f_acc5, %f_a1, %f_b1, %f_acc5;
    fma.rn.f32 %f_acc6, %f_a1, %f_b2, %f_acc6;
    fma.rn.f32 %f_acc7, %f_a1, %f_b3, %f_acc7;
    fma.rn.f32 %f_acc8, %f_a2, %f_b0, %f_acc8;
    fma.rn.f32 %f_acc9, %f_a2, %f_b1, %f_acc9;
    fma.rn.f32 %f_acc10, %f_a2, %f_b2, %f_acc10;
    fma.rn.f32 %f_acc11, %f_a2, %f_b3, %f_acc11;
    fma.rn.f32 %f_acc12, %f_a3, %f_b0, %f_acc12;
    fma.rn.f32 %f_acc13, %f_a3, %f_b1, %f_acc13;
    fma.rn.f32 %f_acc14, %f_a3, %f_b2, %f_acc14;
    fma.rn.f32 %f_acc15, %f_a3, %f_b3, %f_acc15;
    fma.rn.f32 %f_acc16, %f_a4, %f_b0, %f_acc16;
    fma.rn.f32 %f_acc17, %f_a4, %f_b1, %f_acc17;
    fma.rn.f32 %f_acc18, %f_a4, %f_b2, %f_acc18;
    fma.rn.f32 %f_acc19, %f_a4, %f_b3, %f_acc19;
    fma.rn.f32 %f_acc20, %f_a5, %f_b0, %f_acc20;
    fma.rn.f32 %f_acc21, %f_a5, %f_b1, %f_acc21;
    fma.rn.f32 %f_acc22, %f_a5, %f_b2, %f_acc22;
    fma.rn.f32 %f_acc23, %f_a5, %f_b3, %f_acc23;
    fma.rn.f32 %f_acc24, %f_a6, %f_b0, %f_acc24;
    fma.rn.f32 %f_acc25, %f_a6, %f_b1, %f_acc25;
    fma.rn.f32 %f_acc26, %f_a6, %f_b2, %f_acc26;
    fma.rn.f32 %f_acc27, %f_a6, %f_b3, %f_acc27;
    fma.rn.f32 %f_acc28, %f_a7, %f_b0, %f_acc28;
    fma.rn.f32 %f_acc29, %f_a7, %f_b1, %f_acc29;
    fma.rn.f32 %f_acc30, %f_a7, %f_b2, %f_acc30;
    fma.rn.f32 %f_acc31, %f_a7, %f_b3, %f_acc31;
    ld.shared.v4.f32 {%f_a0, %f_a1, %f_a2, %f_a3}, [%r_ab+272];
    ld.shared.v4.f32 {%f_a4, %f_a5, %f_a6, %f_a7}, [%r_ab+288];
    ld.shared.v4.f32 {%f_b0, %f_b1, %f_b2, %f_b3}, [%r_bb+272];
    fma.rn.f32 %f_acc0, %f_a0, %f_b0, %f_acc0;
    fma.rn.f32 %f_acc1, %f_a0, %f_b1, %f_acc1;
    fma.rn.f32 %f_acc2, %f_a0, %f_b2, %f_acc2;
    fma.rn.f32 %f_acc3, %f_a0, %f_b3, %f_acc3;
    fma.rn.f32 %f_acc4, %f_a1, %f_b0, %f_acc4;
    fma.rn.f32 %f_acc5, %f_a1, %f_b1, %f_acc5;
    fma.rn.f32 %f_acc6, %f_a1, %f_b2, %f_acc6;
    fma.rn.f32 %f_acc7, %f_a1, %f_b3, %f_acc7;
    fma.rn.f32 %f_acc8, %f_a2, %f_b0, %f_acc8;
    fma.rn.f32 %f_acc9, %f_a2, %f_b1, %f_acc9;
    fma.rn.f32 %f_acc10, %f_a2, %f_b2, %f_acc10;
    fma.rn.f32 %f_acc11, %f_a2, %f_b3, %f_acc11;
    fma.rn.f32 %f_acc12, %f_a3, %f_b0, %f_acc12;
    fma.rn.f32 %f_acc13, %f_a3, %f_b1, %f_acc13;
    fma.rn.f32 %f_acc14, %f_a3, %f_b2, %f_acc14;
    fma.rn.f32 %f_acc15, %f_a3, %f_b3, %f_acc15;
    fma.rn.f32 %f_acc16, %f_a4, %f_b0, %f_acc16;
    fma.rn.f32 %f_acc17, %f_a4, %f_b1, %f_acc17;
    fma.rn.f32 %f_acc18, %f_a4, %f_b2, %f_acc18;
    fma.rn.f32 %f_acc19, %f_a4, %f_b3, %f_acc19;
    fma.rn.f32 %f_acc20, %f_a5, %f_b0, %f_acc20;
    fma.rn.f32 %f_acc21, %f_a5, %f_b1, %f_acc21;
    fma.rn.f32 %f_acc22, %f_a5, %f_b2, %f_acc22;
    fma.rn.f32 %f_acc23, %f_a5, %f_b3, %f_acc23;
    fma.rn.f32 %f_acc24, %f_a6, %f_b0, %f_acc24;
    fma.rn.f32 %f_acc25, %f_a6, %f_b1, %f_acc25;
    fma.rn.f32 %f_acc26, %f_a6, %f_b2, %f_acc26;
    fma.rn.f32 %f_acc27, %f_a6, %f_b3, %f_acc27;
    fma.rn.f32 %f_acc28, %f_a7, %f_b0, %f_acc28;
